import{_ as d,o as r,c as a,ag as o}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"华天酒店（000428）投资分析","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/stock-investment/huatian-hotel.md","filePath":"topics/stock-investment/huatian-hotel.md"}'),e={name:"topics/stock-investment/huatian-hotel.md"};function n(h,t,s,l,i,g){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="华天酒店-000428-投资分析" tabindex="-1">华天酒店（000428）投资分析 <a class="header-anchor" href="#华天酒店-000428-投资分析" aria-label="Permalink to &quot;华天酒店（000428）投资分析&quot;">​</a></h1><blockquote><p>整理时间：2026-06-16 数据来源：公司年报、公告、湖南日报、湘江财经</p></blockquote><hr><h2 id="一、公司基本信息" tabindex="-1">一、公司基本信息 <a class="header-anchor" href="#一、公司基本信息" aria-label="Permalink to &quot;一、公司基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td><strong>股票代码</strong></td><td>000428（深交所）</td></tr><tr><td><strong>全称</strong></td><td>华天酒店集团股份有限公司</td></tr><tr><td><strong>实控人</strong></td><td>湖南省国资委 → 湖南文体旅产业集团有限公司（2026年3月新增间接控股）</td></tr><tr><td><strong>历史沿革</strong></td><td>1996年上市，2021年控股股东由华天实业→兴湘集团→湖南旅游集团→现文体旅集团</td></tr><tr><td><strong>品牌矩阵</strong></td><td>华天大酒店（五星）/ 华天假日酒店 / 华天精选酒店</td></tr><tr><td><strong>注册地</strong></td><td>长沙市芙蓉区解放东路300号</td></tr></tbody></table><hr><h2 id="二、主营业务结构" tabindex="-1">二、主营业务结构 <a class="header-anchor" href="#二、主营业务结构" aria-label="Permalink to &quot;二、主营业务结构&quot;">​</a></h2><h3 id="_2-1-酒店服务业-主业-85-收入" tabindex="-1">2.1 酒店服务业（主业，85%收入） <a class="header-anchor" href="#_2-1-酒店服务业-主业-85-收入" aria-label="Permalink to &quot;2.1 酒店服务业（主业，85%收入）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>数据</th></tr></thead><tbody><tr><td><strong>2025年收入</strong></td><td>4.49亿元（同比-14.01%）</td></tr><tr><td><strong>客房收入</strong></td><td>1.76亿元（同比-20.43%，毛利率-3.52%）</td></tr><tr><td><strong>餐饮收入</strong></td><td>2.01亿元（同比-1.34%）</td></tr><tr><td><strong>运营模式</strong></td><td>自营+托管，轻资产化</td></tr><tr><td><strong>酒店数量</strong></td><td>直营+托管共55家，已开业48家（直营19+托管29），未开业7家</td></tr><tr><td><strong>会员体系</strong></td><td>累计563万会员</td></tr><tr><td><strong>行业排名</strong></td><td>中国饭店集团60强第33位（较前年升2位）</td></tr><tr><td><strong>地域布局</strong></td><td>湖南为大本营，首次落子西南地区（2025年新开14家托管酒店）</td></tr></tbody></table><h3 id="_2-2-生活服务业-辅业-14-收入" tabindex="-1">2.2 生活服务业（辅业，14%收入） <a class="header-anchor" href="#_2-2-生活服务业-辅业-14-收入" aria-label="Permalink to &quot;2.2 生活服务业（辅业，14%收入）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>业态</th><th>内容</th></tr></thead><tbody><tr><td>洗涤服务</td><td>酒店布草、衣物鞋包中央洗涤</td></tr><tr><td>家政服务</td><td>保洁、收纳</td></tr><tr><td>物业管理</td><td>物业维护</td></tr><tr><td>团餐服务</td><td>膳食经营管理、营养配餐、时鲜配送</td></tr><tr><td>延伸品牌</td><td>华天小卤（餐饮C端输出）</td></tr></tbody></table><p>服务对象涵盖：酒店、学校、企业、机关单位、医疗机构、金融机构、航空系统。</p><hr><h2 id="三、核心财务数据" tabindex="-1">三、核心财务数据 <a class="header-anchor" href="#三、核心财务数据" aria-label="Permalink to &quot;三、核心财务数据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>2025年</th><th>2024年</th><th>同比</th></tr></thead><tbody><tr><td><strong>营业收入</strong></td><td>5.28亿</td><td>6.04亿</td><td>-12.53%</td></tr><tr><td><strong>归母净利润</strong></td><td>-2.10亿</td><td>-1.81亿</td><td>亏损扩大15.98%</td></tr><tr><td><strong>扣非归母净利润</strong></td><td>-2.43亿</td><td>-2.22亿</td><td>亏损扩大9.56%</td></tr><tr><td><strong>经营活动现金流</strong></td><td>0.65亿</td><td>0.88亿</td><td>-25.98%（但仍为正）</td></tr><tr><td><strong>总资产</strong></td><td>44.03亿</td><td>46.27亿</td><td>-4.84%</td></tr><tr><td><strong>归母净资产</strong></td><td>13.39亿</td><td>15.50亿</td><td>-13.61%</td></tr><tr><td><strong>EPS</strong></td><td>-0.2063元</td><td>-0.1779元</td><td>—</td></tr><tr><td><strong>ROE</strong></td><td>-14.56%</td><td>-11.05%</td><td>—</td></tr></tbody></table><blockquote><p>已连续多年亏损。客房毛利率为负（-3.52%），餐饮勉强支撑，整体亏损持续扩大。</p></blockquote><hr><h2 id="四、上下游产业链分析" tabindex="-1">四、上下游产业链分析 <a class="header-anchor" href="#四、上下游产业链分析" aria-label="Permalink to &quot;四、上下游产业链分析&quot;">​</a></h2><h3 id="_4-1-上游" tabindex="-1">4.1 上游 <a class="header-anchor" href="#_4-1-上游" aria-label="Permalink to &quot;4.1 上游&quot;">​</a></h3><table tabindex="0"><thead><tr><th>上游</th><th>说明</th></tr></thead><tbody><tr><td><strong>物业/地产</strong></td><td>老牌酒店资产重，华天城模式后遗症（酒店+房地产捆绑）造成大量资产沉淀</td></tr><tr><td><strong>人力</strong></td><td>酒店属于劳动密集型，长沙区域共享改革（近10家酒店人力成本共享）在推进中</td></tr><tr><td><strong>原材料</strong></td><td>餐饮原材料采购（食品、食材供应链）</td></tr><tr><td><strong>设备/装修</strong></td><td>酒店维护、翻新成本</td></tr></tbody></table><h3 id="_4-2-下游" tabindex="-1">4.2 下游 <a class="header-anchor" href="#_4-2-下游" aria-label="Permalink to &quot;4.2 下游&quot;">​</a></h3><table tabindex="0"><thead><tr><th>下游</th><th>说明</th></tr></thead><tbody><tr><td><strong>商务出差人群</strong></td><td>核心客群，商务需求持续走弱是收入下滑主因</td></tr><tr><td><strong>旅游客群</strong></td><td>旅游酒店消费，随文旅复苏有一定需求</td></tr><tr><td><strong>B端企业</strong></td><td>团餐、物业、洗衣等企业客户</td></tr><tr><td><strong>C端家庭</strong></td><td>正在开拓的新方向：居家管家服务（保洁/餐饮/宠物/收纳）</td></tr><tr><td><strong>关联方</strong></td><td>向湖南文体旅集团申请不超过1亿元财务资助</td></tr></tbody></table><hr><h2 id="五、转型战略与-第二增长曲线" tabindex="-1">五、转型战略与&quot;第二增长曲线&quot; <a class="header-anchor" href="#五、转型战略与-第二增长曲线" aria-label="Permalink to &quot;五、转型战略与&quot;第二增长曲线&quot;&quot;">​</a></h2><h3 id="现状判断" tabindex="-1">现状判断 <a class="header-anchor" href="#现状判断" aria-label="Permalink to &quot;现状判断&quot;">​</a></h3><p>管理层用&quot;舍、断、离&quot;形容当下处境：</p><ul><li><strong>舍</strong>：剥离沉淀资产（六大华天城后遗症）</li><li><strong>断</strong>：切断亏损业务线</li><li><strong>离</strong>：轻资产化转型（托管模式扩张）</li></ul><h3 id="三条主线" tabindex="-1">三条主线 <a class="header-anchor" href="#三条主线" aria-label="Permalink to &quot;三条主线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>主线</th><th>具体动作</th></tr></thead><tbody><tr><td><strong>轻资产扩张</strong></td><td>托管模式，2025年新签约14家酒店，首次进入西南地区</td></tr><tr><td><strong>生活服务&quot;做宽&quot;</strong></td><td>洗衣/家政/物业/团餐，已有7400万年收入基础</td></tr><tr><td><strong>C端管家服务</strong></td><td>五星级服务进家庭：年度订阅制，上门保洁+餐饮+宠物+收纳</td></tr></tbody></table><h3 id="c端管家服务的想象空间" tabindex="-1">C端管家服务的想象空间 <a class="header-anchor" href="#c端管家服务的想象空间" aria-label="Permalink to &quot;C端管家服务的想象空间&quot;">​</a></h3><blockquote><p>股东会上媒体人建议：将华天五星级服务标准化输出到家庭，管理层&quot;频频点头&quot;。</p></blockquote><ul><li><strong>信任优势</strong>：国企背书+30年品牌，解决家政行业&quot;信任赤字&quot;</li><li><strong>能力复用</strong>：现有清洁团队、中央洗涤工厂、星级厨师天然平移</li><li><strong>变现路径</strong>：年度订阅套餐 → 交叉销售（保洁推餐饮、物业推洗涤）</li><li><strong>已有验证</strong>：华天小卤从酒店厨房走向街头，证明餐饮能力可C端化</li></ul><hr><h2 id="六、关键风险" tabindex="-1">六、关键风险 <a class="header-anchor" href="#六、关键风险" aria-label="Permalink to &quot;六、关键风险&quot;">​</a></h2><table tabindex="0"><thead><tr><th>风险</th><th>说明</th></tr></thead><tbody><tr><td><strong>主业持续亏损</strong></td><td>客房毛利率-3.52%，需求端无改善信号</td></tr><tr><td><strong>历史包袱沉重</strong></td><td>六大华天城资产沉淀，资产盘活进度不确定</td></tr><tr><td><strong>行业竞争激烈</strong></td><td>湖南/长沙酒店供给饱和，商务需求走弱</td></tr><tr><td><strong>关联交易依赖</strong></td><td>向文体旅集团申请财务资助1亿，输血依赖</td></tr><tr><td><strong>转型不确定性</strong></td><td>C端管家服务尚未成型，能否规模化存疑</td></tr></tbody></table><hr><h2 id="七、股权结构" tabindex="-1">七、股权结构 <a class="header-anchor" href="#七、股权结构" aria-label="Permalink to &quot;七、股权结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>股东</th><th>持股比例</th></tr></thead><tbody><tr><td>湖南旅游发展投资集团有限公司</td><td>32.48%</td></tr><tr><td>湖南华信恒源股权投资企业</td><td>22.72%</td></tr><tr><td>其他</td><td>&lt;2%为主</td></tr></tbody></table><hr><h2 id="八、一句话总结" tabindex="-1">八、一句话总结 <a class="header-anchor" href="#八、一句话总结" aria-label="Permalink to &quot;八、一句话总结&quot;">​</a></h2><blockquote><p>华天酒店是一家<strong>品牌老、包袱重、转型难</strong>的湖南地方国企酒店。主业客房亏、餐饮平，生活服务7400万是唯一亮点，C端管家服务是管理层认可的新方向，但能否落地尚未可知。当前<strong>连续亏损+现金流为正</strong>的组合说明：公司还没死，但也没有找到明确的&quot;救命稻草&quot;。</p></blockquote>',41)])])}const c=d(e,[["render",n]]);export{u as __pageData,c as default};
